// One app-wide toast bus: every page and modal publishes to the same viewport.
const toastListeners = new Set();
function publishToast(type, title, message='') {
  const toast = { id: `${Date.now()}-${Math.random()}`, type, title, message };
  toastListeners.forEach(listener => listener(toast));
}
function readRequest(path, options) { return requestJson(API + path, options); }
async function request(path, options) {
  try {
    return await requestJson(API + path, options);
  } catch (error) {
    publishToast('error', error.title || 'Thao tác chưa thành công', error.message);
    throw error;
  }
}
function ToastViewport() {
  const [items, setItems] = useState([]);
  useEffect(() => {
    const listener = toast => {
      setItems(current => [...current, toast].slice(-5));
      const duration = toast.type === 'error' ? 6500 : toast.type === 'warning' ? 5000 : 3500;
      window.setTimeout(() => setItems(current => current.filter(item => item.id !== toast.id)), duration);
    };
    toastListeners.add(listener);
    return () => toastListeners.delete(listener);
  }, []);
  const dismiss = id => setItems(current => current.filter(item => item.id !== id));
  return <div className="toast-viewport" aria-live="polite" aria-atomic="false">
    {items.map(item => <div className={`toast-card toast-${item.type}`} key={item.id} role="status">
      <div className="toast-symbol">{item.type==='success'?<CheckCircle2/>:item.type==='warning'?<AlertCircle/>:item.type==='info'?<Bell/>:<AlertCircle/>}</div>
      <div className="toast-copy"><b>{item.title}</b>{item.message&&<p>{item.message}</p>}</div>
      <button className="toast-close" aria-label="Đóng thông báo" onClick={()=>dismiss(item.id)}>×</button>
      <span className="toast-progress"/>
    </div>)}
  </div>;
}
